const fs = require('fs');
function rep(p, pairs) {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of pairs) {
    if (!s.includes(a)) throw new Error('not found in ' + p + ': ' + a.slice(0, 60));
    s = s.replace(a, b);
  }
  fs.writeFileSync(p, s);
}
